package com.resumeanalyzer.controller;
import com.resumeanalyzer.dto.AnalysisResponseDto; import com.resumeanalyzer.dto.JobMatchDto; import com.resumeanalyzer.dto.ResumeHistoryDto; import com.resumeanalyzer.repository.ResumeRepository; import com.resumeanalyzer.security.CurrentUser; import com.resumeanalyzer.service.JobMatchService; import com.resumeanalyzer.service.ResumeService; import lombok.RequiredArgsConstructor; import lombok.extern.slf4j.Slf4j; import org.springframework.http.MediaType; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.List;
@RestController @RequestMapping("/api/v1/resumes") @RequiredArgsConstructor @Slf4j public class ResumeController { private final ResumeService resumes; private final JobMatchService jobs; private final ResumeRepository resumeRepository; private final CurrentUser currentUser; @PostMapping(value="/upload",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) AnalysisResponseDto upload(@RequestPart("file") MultipartFile file,@RequestPart(value="jobDescription",required=false) String jobDescription){return resumes.uploadAndAnalyze(file,jobDescription);} @GetMapping("/job-matches") List<JobMatchDto> jobMatches(){try{return jobs.findMatches();}catch(RuntimeException exception){log.error("Live job feed failed; returning resume-based search links",exception);return jobs.fallbackMatches();}} @Transactional(readOnly=true) @GetMapping("/history") List<ResumeHistoryDto> history(){return resumeRepository.findHistoryByUserId(currentUser.require().getId());} }
